#include <juce_audio_utils/juce_audio_utils.h>
#include <iostream>
#include <stdexcept>
int main(int argc,char**argv){juce::ScopedJuceInitialiser_GUI gui;try{if(argc!=3)throw std::runtime_error("usage: host bundle directory");juce::VST3PluginFormat fmt;juce::OwnedArray<juce::PluginDescription>types;fmt.findAllTypesForFile(types,argv[1]);if(types.size()!=1||types[0]->name!="BLP BL1176")throw std::runtime_error("identity");juce::File dir(argv[2]);for(int rate:{44100,48000})for(int mode:{0,1,2,3,4,5}){juce::String error;auto p=fmt.createInstanceFromDescription(*types[0],rate,257,error);if(!p)throw std::runtime_error("load");bool found=false;for(auto*a:p->getParameters()){auto name=a->getName(100);if(name=="Ratio"){found=true;if(fabs(a->getDefaultValue()-.5)>1e-6)throw std::runtime_error("12:1 default");a->setValueNotifyingHost((mode<5?mode:2)/4.f);}if(name=="Bypass"&&mode==5)a->setValueNotifyingHost(1);}if(!found)throw std::runtime_error("ratio missing");p->prepareToPlay(rate,257);juce::MidiBuffer midi;juce::AudioBuffer<float>warm(2,257);for(int k=0;k<20;k++){warm.clear();p->processBlock(warm,midi);}p->releaseResources();p->prepareToPlay(rate,257);juce::MemoryBlock bytes;dir.getChildFile("dry-"+juce::String(rate)+".f32").loadFileAsData(bytes);auto*x=(float*)bytes.getData();int n=int(bytes.getSize()/8);if(!n)throw std::runtime_error("empty input");std::vector<float>out(n*2);double err=0,peak=0;for(int pos=0;pos<n;pos+=257){int count=std::min(257,n-pos);juce::AudioBuffer<float>b(2,count);for(int c=0;c<2;c++)for(int i=0;i<count;i++)b.setSample(c,i,x[2*(pos+i)+c]);p->processBlock(b,midi);for(int c=0;c<2;c++)for(int i=0;i<count;i++){float y=b.getSample(c,i);if(!std::isfinite(y))throw std::runtime_error("nonfinite");out[2*(pos+i)+c]=y;peak=std::max(peak,double(fabs(y)));err=std::max(err,double(fabs(y-x[2*(pos+i)+c])));}}if(mode==5&&err!=0)throw std::runtime_error("bypass transparency");if(mode<5)dir.getChildFile("updated-"+juce::String(rate)+"-"+juce::String(mode)+".f32").replaceWithData(out.data(),out.size()*4);std::cout<<"PASS actual VST3 "<<rate<<" Hz mode "<<mode<<" finite output peak="<<peak<<(mode==5?", exact bypass":"")<<std::endl;}std::cout<<"PASS new instance ratio default 12:1"<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
